3	// steps move on: the introduction over the museum photo (with car.look, the one thing to find on the exhibit), one step
4	// per component in 3D, then background back on the photo with the car outline (car.takeaway first). A component step reads
5	// as one experiment: its prompt, the mechanism's key cards, its answer, a photo of the real part where the exhibit hides it
6	// (component.real), then the rest under a disclosure named by component.more (panel.js `detail`); without `more` its cards
7	// and technical facts follow in order. The step at the reading line sets what the stage shows; only stages on screen run
8	// their frame loop. Tapping a real-part photo swaps it with the stage, for a close look; tapping either again, or scrolling
9	// the photo's place out of view, swaps them back.
10	import { t, keepOnSwitch, resumed } from "./i18n.js";
11	import { h, link } from "./dom.js";
12	import { stageElement, mountViewer, caveats } from "./viewer.js";
13	
14	// A step is its content and what the stage shows while it is at the reading line.
15	const step = (state, ...kids) => ({ state, el: h("section", { class: "step" }, kids) });
16	// What to look at on the real car, before the model and after it.
17	const look = (label, text) => (text ? h("p", { class: "look" }, h("b", {}, label), " ", text) : null);
