19	// The mechanism in real life (component.real): a photo of the same kind of part, for one this exhibit hides.
20	// Its picture is a button that swaps it with the stage (story's `swap`).
21	const real = r => (r ? h("figure", { class: "real" },
22	  h("div", { class: "real-media", "data-back": t("Tap the 3D view to swap back") },
23	    h("button", { type: "button", class: "real-open", "aria-label": t("Show this photo large, in place of the 3D view") },
24	      h("img", { src: r.src, alt: r.alt, width: r.w, height: r.h, loading: "lazy", decoding: "async" }))),
25	  h("figcaption", {}, h("b", {}, t("In real life:")), " ", r.caption, " ",
26	    h("span", { class: "credit" }, t("Photo:"), " ", link(r.credit.url, r.credit.author), `, ${r.credit.license}`))) : null);
27	
28	// A component's step, with the elements its panel cards go into.
29	function compStep(c) {
30	  const main = h("div", { class: "cards" }), detail = c.more ? h("div", { class: "cards" }) : main;
31	  const st = step({ comp: c.id, view: "model", outline: false }, h("h3", {}, c.label),
32	    c.prompt ? h("p", { class: "prompt" }, c.prompt) : null, main, c.answer ? h("p", { class: "answer" }, c.answer) : null,
