44	      look(t("At the car:"), car.look)),
45	    ...comps,
46	    step({ comp: first, view: "photo", outline: true }, look(t("Back at the car:"), car.takeaway), h("footer", {}, h("h3", {}, t("Background")),
47	      h("p", {}, t("Back on the museum photo: the mechanism where it sits, inside the car's outline.")),
