59	// orbit drag or pinch) swaps back; so does check(), called on scroll, once the photo's place is out of view (above the
60	// pinned stage area or below the screen).
61	function swapper(el, stageEl) {
62	  let media = null;   // the .real-media now holding the stage
63	  const back = () => {
64	    if (!media) return;
65	    const btn = el.querySelector(".story-stage .real-open");
66	    btn.replaceWith(stageEl); media.append(btn); btn.removeAttribute("style");
67	    btn.setAttribute("aria-label", t("Show this photo large, in place of the 3D view"));
68	    media.classList.remove("swapped"); media = null;
69	  };
70	  const swap = m => {
71	    back();
72	    const btn = m.querySelector(".real-open");
73	    btn.setAttribute("style", stageEl.getAttribute("style") ?? "");   // the stage's aspect: the pinned area keeps its size
74	    stageEl.replaceWith(btn); m.append(stageEl);
