76	    m.classList.add("swapped"); media = m;
77	  };
78	  for (const btn of el.querySelectorAll(".real-open")) {
79	    btn.addEventListener("click", () => (btn.closest(".real-media") ? swap(btn.closest(".real-media")) : back()));
80	  }
