102	      s.viewer.show(s.steps[0].state);
103	    } catch (err) {
104	      console.error(err);
105	      s.stageEl.after(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; once it has loaded online, it also works offline.")));
106	    }
107	  }));
108	
109	  // The reading line: halfway down the screen beside the pinned stage, or halfway down the part it leaves free below it.
110	  // The last step whose top has passed the line is the one shown.
111	  function reading(s) {
112	    const pane = s.el.querySelector(".story-stage").getBoundingClientRect(), beside = s.steps[0].el.getBoundingClientRect().left >= pane.right;
113	    return { pane, line: beside ? innerHeight / 2 : (pane.bottom + innerHeight) / 2 };
114	  }
