133	  function mark(s, k) { s.mark = { step: k, past: reading(s).line - s.steps[k].el.getBoundingClientRect().top, when: ++clock }; }
134	  for (const s of stories) {
135	    const used = e => {
136	      if (replaying || !e.target.closest?.(".panel button, .panel input")) return;
137	      const k = s.steps.findIndex(st => st.el.contains(e.target));
138	      if (k > 0) { s.used = true; mark(s, k); }
139	    };
140	    s.el.addEventListener("click", used); s.el.addEventListener("input", used);
141	  }
142	  // Across the switch: each story's settings and open disclosures, and that mark, so the visitor finds the same experiment
143	  // in the same place.
144	  const details = s => [...s.el.querySelectorAll("details")];
145	  keepOnSwitch(() => {
146	    const last = stories.filter(s => s.mark).sort((a, b) => b.mark.when - a.mark.when)[0];
147	    return {
148	      stories: Object.fromEntries(stories.map(s => [s.car.slug, { settings: s.viewer?.settings(), open: details(s).flatMap((d, i) => (d.open ? [i] : [])) }])),
149	      at: last ? { slug: last.car.slug, step: last.mark.step, past: last.mark.past, used: !!last.used } : null,
150	    };
151	  });
152	  const back = resumed();
153	  if (back) {
154	    for (const s of stories) {
155	      const kept = back.stories?.[s.car.slug];
156	      if (!kept) continue;
157	      replaying = true; s.viewer?.restore(kept.settings); replaying = false;
158	      const ds = details(s); for (const i of kept.open ?? []) if (ds[i]) ds[i].open = true;
159	    }
160	    const s = stories.find(x => x.car.slug === back.at?.slug), st = s?.steps[back.at.step];
161	    if (st) {   // step to the top first, so its story's stage is pinned and the reading line is where it will be
162	      st.el.scrollIntoView({ block: "start" });
163	      const past = Math.max(1, Math.min(back.at.past, st.el.offsetHeight - 1));
164	      scrollBy(0, st.el.getBoundingClientRect().top - reading(s).line + past);
165	      s.used = back.at.used; mark(s, back.at.step);   // a second switch keeps the same place
166	    }
167	    history.scrollRestoration = "auto";
168	  }
169	
170	  let queued = false;
171	  const schedule = () => { if (!queued) { queued = true; requestAnimationFrame(() => { queued = false; pick(); }); } };
172	  addEventListener("scroll", schedule, { passive: true });
173	  addEventListener("resize", schedule);
174	  pick();
175	
176	  // Only stages on screen animate: several scenes at once, one of them a live wind tunnel, would be too much for a phone.
177	  const onScreen = new IntersectionObserver(entries => {
178	    for (const e of entries) { const v = stories.find(s => s.stageEl === e.target).viewer; if (e.isIntersecting) v.start(); else v.stop(); }
179	  });
180	  for (const s of stories) if (s.viewer) onScreen.observe(s.stageEl);
181	
182	  return stories.map(s => ({
183	    slug: s.car.slug, step: () => s.at, state: () => s.viewer?.state, swapped: s.swapped,
184	    frames: () => s.viewer?.stage.stats.frames ?? 0, project: p => s.viewer?.project(p), triangles: () => s.viewer?.stage.renderer.info.render.triangles ?? 0,
185	  }));
186	}
