1	// Page shell for every stop: stop.html?s=<slug>[&r=teaser]. Builds the page from stops/tour.js + stops/<slug>/car.js: the
2	// car's scroll story (story.js), where it is on the route, and prev/next.
3	// With r=teaser (links from teaser.html) prev/next, the stop count and the back link stay within the teaser.
4	import tour, { teaser } from "../../stops/tour.js";
5	import { registerOffline } from "./offline.js";
6	import { t, loadCar, localizePage, missing } from "./i18n.js";
7	import { h, link } from "./dom.js";
8	import { story, play } from "./story.js";
9	
10	const params = new URLSearchParams(location.search);
11	const slug = params.get("s");
12	const teaserStops = tour.filter(s => teaser.includes(s.slug));
13	const inTeaser = params.get("r") === "teaser" && teaserStops.some(s => s.slug === slug);
14	const route = inTeaser ? teaserStops : tour;
15	const idx = route.findIndex(s => s.slug === slug);   // validated before any dynamic import
16	const app = document.getElementById("app");
17	
18	localizePage();
19	registerOffline();
20	if (inTeaser) Object.assign(document.getElementById("back"), { href: "teaser.html", textContent: t("← Highlights") });
21	if (idx < 0) {
22	  document.title = t("Stop not found · Museum tour");
23	  app.replaceChildren(h("h1", {}, t("Stop not found")), h("p", {}, t("This QR code or link does not match a stop on the tour."), " ", link("./", t("Open the tour route"))));
24	} else {
25	  main().catch(err => {
26	    console.error(err);
27	    app.append(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; once it has loaded online, it also works offline.")));
28	  });
29	}
30	
31	async function main() {
32	  const stop = route[idx];
33	  const car = await loadCar(stop.slug);
34	  document.title = t("{0} · Museum tour", car.name);
35	  const prev = route[idx - 1], next = route[idx + 1], here = s => `stop.html?s=${s.slug}${inTeaser ? "&r=teaser" : ""}`;
36	  const nameOf = async s => (s ? (await loadCar(s.slug)).name : null);
37	  const [prevName, nextName] = await Promise.all([nameOf(prev), nameOf(next)]);
38	  const s = story(car, { title: "h1" });
39	  document.getElementById("where").textContent = t("Stop {0} of {1} · {2} · Level {3}", idx + 1, route.length, t(stop.room), stop.level)
40	    + (stop.check ? ` · ${stop.check === "level" ? t("level not yet checked") : t("room not yet checked")}` : "");
41	  app.replaceChildren(s.el,
42	    h("nav", { class: "pager", "aria-label": t("Previous and next stop") },
43	      prev ? link(here(prev), `← ${prevName}`) : h("span"), next ? link(here(next), `${nextName} →`) : h("span")),
44	    h("p", { class: "note" }, t("Unofficial private tour notes, not affiliated with Mercedes-Benz. 3D: three.js (MIT). Mechanisms are original code from illustrative hardpoints.")));
45	  const handles = await play([s]);
46	  if (params.has("debug")) window.__tour = { stories: handles, missing: () => [...missing], ready: true };
47	}
48

