1	// Route page (index.html): the stops grouped by room in walking order as photo cards, a jump list to the rooms (native
2	// fragment links; the hero's "Find your room" leads to it), plus offline status. Each card is one link: photo, familiar
3	// name, year and the car's question (its summary until it has one). Car configs are pure data, so this imports them without loading three.js. teaser.html has
4	// its own page script, teaser.js.
5	import tour from "../../stops/tour.js";
6	import { showOfflineStatus } from "./offline.js";
7	import { t, loadCar, localizePage } from "./i18n.js";
8	
9	localizePage();
10	showOfflineStatus(document.getElementById("status"));
11	
12	const route = document.getElementById("route");
13	const cars = await Promise.all(tour.map(s => loadCar(s.slug)));
14	const rooms = [];
15	tour.forEach((s, i) => {
16	  const key = `${s.room} · Level ${s.level}`;
17	  if (rooms.at(-1)?.key !== key) rooms.push({ key, id: `room-${s.room.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`, name: s.room, level: s.level, stops: [] });
18	  rooms.at(-1).stops.push({ s, car: cars[i], n: i + 1 });
19	});
20	
21	const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
22	const levelNote = room => (room.stops.some(({ s }) => s.check === "level") ? ` · ${t("level not yet checked")}` : "");
23	
24	const jump = document.getElementById("jump");
25	jump.querySelector("ul").replaceChildren(...rooms.map(room => {
26	  const a = el("a", "pill"); a.href = `#${room.id}`;
27	  a.append(el("span", null, t(room.name)), el("small", null, t("Level {0}", room.level)));
28	  const li = el("li"); li.append(a); return li;
29	}));
30	jump.hidden = false;
31	
32	route.replaceChildren(...rooms.map(room => {
33	  const li = el("li", "room"), head = el("div", "room-head"), count = room.stops.length;
34	  li.id = room.id;
35	  head.append(el("h2", null, t(room.name)), el("span", null, (count === 1 ? t("Level {0} · 1 stop", room.level) : t("Level {0} · {1} stops", room.level, count)) + levelNote(room)));
36	  const ul = el("ul", "stops");
37	  for (const { s, car, n } of room.stops) {
38	    const a = document.createElement("a"); a.href = `stop.html?s=${s.slug}`;
39	    if (car.photo) {   // decorative inside the link: the car's name is the link text
40	      const img = Object.assign(document.createElement("img"), { src: `stops/${s.slug}/${car.photo.src}`, alt: "", width: car.photo.w, height: car.photo.h, loading: "lazy", decoding: "async" });
41	      const pic = el("div", "pic"); pic.append(img); a.append(pic);
42	    }
43	    const pill = el("span", "pill primary", t("See it working"));
44	    const arrow = el("i", null, "›"); arrow.setAttribute("aria-hidden", "true"); pill.append(arrow);
45	    const text = el("div", "text");
46	    text.append(el("small", null, t("Stop {0} · {1}", n, car.year)), el("b", null, car.name), el("p", car.question ? "question" : null, car.question ?? car.summary));
47	    if (car.photo?.caption) text.append(el("p", "caption", car.photo.caption));
48	    if (s.check === "room") text.append(el("p", "caption", t("Room not yet checked: it may stand elsewhere")));
49	    text.append(pill);
50	    a.append(text);
51	    const item = el("li", "stop"); item.append(a); ul.append(item);
52	  }
53	  li.append(head, ul);
54	  return li;
55	}));
56	
57	// Photo credits from the car data, so the line stays true as stops are added.
58	const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
59	document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each stop links its photo's source.", credits.join(", "));
60	
61	// The room picker and the rooms exist only now: a link to one of them (index.html#jump, the highlights page's
62	// "See the full route", or #room-legend-6) lands here, as does a tap on "Find your room" before they were built.
63	const target = location.hash.slice(1);
64	if (target === "jump" || target.startsWith("room-")) document.getElementById(target)?.scrollIntoView();
65

