1	// Front steering geometry, top view. Pure: no DOM, no three.js.
2	// Frame in mm: x forward, y left; front axle at x = 0, rear axle at x = −wheelbase. Steer angle δ in rad, + = turning left.
3	const hyp = Math.hypot;
4	const rot = ([x, y], a) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)];
5	
6	// Double-pivot (stub-axle) steering with a trapezoid linkage: kingpins at (0, ±k), steering arms of length a pointing
7	// rearwards and inwards by β, joined by one tie rod. β = atan(k / wheelbase) aims both arms at the rear-axle centre,
8	// the classic condition for the wheel axes to meet near one point (Ackermann).
9	export function createDoublePivot({ kingpinHalf: k, arm: a, wheelbase: wb, armAngle }) {
10	  const beta = armAngle ?? Math.atan(k / wb);
11	  const KL = [0, k], KR = [0, -k];
12	  const armVec = (side, d) => rot([-a * Math.cos(beta), -side * a * Math.sin(beta)], d);
13	  const end = (K, side, d) => { const v = armVec(side, d); return [K[0] + v[0], K[1] + v[1]]; };
14	  const tie = hyp(...[0, 1].map(i => end(KL, 1, 0)[i] - end(KR, -1, 0)[i]));
15	
16	  // Given the left wheel's angle (driven by the steering column), close the tie rod for the right wheel.
17	  function solve(dL) {
18	    const PL = end(KL, 1, dL);
19	    const dx = PL[0] - KR[0], dy = PL[1] - KR[1], d = hyp(dx, dy);
20	    const along = (a * a - tie * tie + d * d) / (2 * d), h = Math.sqrt(Math.max(0, a * a - along * along));
21	    const mx = KR[0] + along * dx / d, my = KR[1] + along * dy / d;
22	    const cands = [[mx + h * dy / d, my - h * dx / d], [mx - h * dy / d, my + h * dx / d]];
23	    const guess = end(KR, -1, dL);
24	    const PR = cands.reduce((best, c) => (hyp(c[0] - guess[0], c[1] - guess[1]) < hyp(best[0] - guess[0], best[1] - guess[1]) ? c : best));
25	    const v0 = armVec(-1, 0), v = [PR[0] - KR[0], PR[1] - KR[1]];
26	    const raw = Math.atan2(v[1], v[0]) - Math.atan2(v0[1], v0[0]);
27	    const dR = Math.atan2(Math.sin(raw), Math.cos(raw));   // wrap to (−π, π]
28	    return { dL, dR, PL, PR, KL, KR, ...turning(dL, dR) };
29	  }
30	
31	  // Each front wheel's axis meets the rear-axle line at y = ±k + wb / tan δ. Equal y's = no tyre scrub.
32	  function turning(dL, dR) {
33	    if (Math.abs(dL) < 1e-6 || Math.abs(dR) < 1e-6) return { icrL: Infinity, icrR: Infinity, radius: Infinity, idealOuter: 0 };
34	    const icrL = k + wb / Math.tan(dL), icrR = -k + wb / Math.tan(dR);
35	    const inner = Math.max(Math.abs(dL), Math.abs(dR));
36	    const idealOuter = Math.sign(dL) * Math.atan(1 / (1 / Math.tan(inner) + 2 * k / wb));
37	    const icrY = (icrL + icrR) / 2, outerK = dL > 0 ? KR : KL;
38	    return { icrL, icrR, idealOuter, radius: hyp(-wb - outerK[0], icrY - outerK[1]) };
39	  }
40	
41	  return { k, a, wb, beta, tie, solve, armVec };
42	}
