49	  const icrY = straight ? Infinity : wb / Math.tan(d), outer = d > 0 ? R : L;
50	  return { L, R, halfTrack: k * Math.cos(d), swingBack: k * Math.abs(Math.sin(d)), icrY, radius: straight ? Infinity : hyp(outer[0] + wb, outer[1] - icrY) };
51	}
52	
53	// Two steered front axles (twin-steer lorries): axle 1 `wheelbase` ahead of the rear axle, axle 2 `second` ahead of it.
54	// For every wheel axis to meet at one turning centre on the rear-axle line, the second axle must steer less: for the same
55	// centre tan δ₂ = tan δ₁ · second / wheelbase, which a drag link between the two axles' steering arms provides. Each axle
56	// is its own double-pivot trapezoid aimed at the rear axle. steered = false: the second axle runs straight (its tyres are
57	// dragged sideways through every turn, at the slip angle they would need to point at the centre).
58	export function createTwinSteer({ kingpinHalf, arm, wheelbase, second }) {
59	  const a1 = createDoublePivot({ kingpinHalf, arm, wheelbase }), a2 = createDoublePivot({ kingpinHalf, arm, wheelbase: second });
60	  const link = d => Math.atan(Math.tan(d) * second / wheelbase);
61	  return {
62	    a1, a2, link,
63	    solve(dL, steered = true) {
64	      const s1 = a1.solve(dL), s2 = steered ? a2.solve(link(dL)) : a2.solve(0);
65	      const centre = (s1.icrL + s1.icrR) / 2;   // y of the turning centre on the rear-axle line (Infinity straight ahead)
66	      const scrub = Number.isFinite(centre) ? Math.atan(second / Math.abs(centre)) : 0;   // slip angle forced on a straight axle 2
67	      return { s1, s2, centre, miss: steered && Number.isFinite(s2.icrL) ? Math.abs((s2.icrL + s2.icrR) / 2 - centre) : null, scrub: steered ? 0 : scrub };
