3	// createTwinSteer). Fix the second axle straight and its tyres are scrubbed sideways through every turn instead.
4	// Params (mm, deg; ground at z = 0): label, rear (rear axle x), wheelbase (rear → first axle), second (rear → second
5	// axle), kingpinHalf, arm, halfTrack (wheel centres), wheelR, rearHalfTrack, maxSteer.
6	import * as THREE from "three";
7	import { V, mat, rod, place, ball, tyre } from "../lib/scene/helpers.js";
8	import { createTwinSteer } from "../lib/model/steering.js";
9	
10	const D = Math.PI / 180, FAR = 60;   // m: axis lines longer than this are not drawn (nearly straight ahead)
11	
12	export function create(ctx, p) {
13	  const { stage, carRoot, t } = ctx, m = v => v / 1000;
14	  const sys = createTwinSteer({ kingpinHalf: p.kingpinHalf, arm: p.arm, wheelbase: p.wheelbase, second: p.second });
15	  const R = m(p.wheelR), x0 = m(p.rear), k = m(p.kingpinHalf), off = m(p.halfTrack - p.kingpinHalf);
16	  const group = new THREE.Group(); carRoot.add(group);
17	  const tyreMat = mat(0x2a2d31, { roughness: 0.9, transparent: true }), beamMat = stage.tokenMat("--metal", { metalness: 0.4 });
18	  const linkMat = stage.tokenMat("--l1"), scrubMat = mat(0x2a2d31, { roughness: 0.9, transparent: true }); stage.bind(scrubMat.color, "--accent");
19	  const axisMat = new THREE.LineDashedMaterial({ dashSize: 0.15, gapSize: 0.1, transparent: true, opacity: 0.8 }); stage.bind(axisMat.color, "--l2");
20	  const wheel = () => { const g = new THREE.Group(), w = tyre(tyreMat, R - 0.1, 0.1); g.add(w); g.userData.t = w; group.add(g); return g; };
21	
22	  // Rear axle (fixed), and per front axle a beam, two wheels on their kingpins, and two axis lines to the rear-axle line.
23	  group.add(place(rod(beamMat, 0.03), V(x0, -m(p.rearHalfTrack), R), V(x0, m(p.rearHalfTrack), R)));
24	  for (const s of [1, -1]) wheel().position.set(x0, s * m(p.rearHalfTrack), R);
25	  const axles = [p.wheelbase, p.second].map(wb => {
26	    const x = x0 + m(wb);
27	    group.add(place(rod(beamMat, 0.035), V(x, -k, R), V(x, k, R)));
28	    const wheels = [1, -1].map(() => wheel());
29	    const lines = [0, 1].map(() => { const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([V(0, 0, 0), V(1, 0, 0)]), axisMat); l.frustumCulled = false; group.add(l); return l; });
30	    return { x, wheels, lines };
31	  });
32	  const link = rod(linkMat, 0.018); group.add(link);
33	  const centre = ball(stage.tokenMat("--accent"), 0.09, V(x0, 0, 0.05)); group.add(centre);
34	
35	  // ---------- state + panel ----------
36	  let steer = 0, target = 20 * D, steered = true, demo = !ctx.reducedMotion, phase = 0;
37	  const ui = ctx.panel([{ label: p.label, badge: { id: "state", text: "" }, items: [
38	    { buttons: [{ id: "linked", label: t("Second axle steered"), pressed: true, onClick: () => setLinked(true) }, { id: "fixed", label: t("Second axle fixed"), pressed: false, onClick: () => setLinked(false) }] },
39	    { slider: { id: "steer", label: t("Steering, first axle inner wheel (deg)"), min: -p.maxSteer, max: p.maxSteer, step: 1, value: 20, onInput: v => { stopDemo(); target = v * D; } } },
40	    { readouts: [{ id: "a1", label: t("First axle"), unit: t("deg inner / outer") }, { id: "a2", label: t("Second axle"), unit: t("deg inner / outer") },
41	      { id: "radius", label: t("Turning radius"), unit: t("m at the rear axle") }, { id: "scrub", label: t("Second-axle tyres dragged sideways"), unit: t("deg slip") }] },
42	    { buttons: [{ id: "auto", toggle: [t("Demo on"), t("Demo off")], pressed: demo, onClick: v => (demo = v) }] },
43	  ] }, { label: t("Parts"), items: [{ legend: [["--metal", t("Axle beams")], ["--l1", t("Drag link between the axles")], ["--l2", t("Wheel axes, drawn out to the rear-axle line")], ["--accent", t("Turning centre / scrubbing tyres")]] }] }]);
44	  function stopDemo() { if (demo) { demo = false; ui.toggle("auto").set(false); } }
45	  function setLinked(on) { steered = on; ui.toggle("linked").set(on); ui.toggle("fixed").set(!on); }
46	
47	  const tmp = V(0, 0, 0);
48	  return {
49	    layout({ active, onPhoto }) { group.visible = active; tyreMat.opacity = scrubMat.opacity = onPhoto ? 0.15 : 1; for (const a of axles) a.lines.forEach(l => (l.visible = !onPhoto)); centre.visible = !onPhoto; },
50	    update(dt) {
51	      if (demo) { phase += dt * 0.5; target = Math.sin(phase) * p.maxSteer * 0.8 * D; }
52	      steer += (target - steer) * Math.min(1, dt * 6);
53	      const r = sys.solve(steer, steered), sols = [r.s1, r.s2];
54	      axles.forEach((a, i) => {
55	        const s = sols[i];
56	        [s.dL, s.dR].forEach((d, j) => {
57	          const side = j ? -1 : 1, w = a.wheels[j];
58	          w.position.set(a.x - off * Math.sin(d) * side, side * (k + off * Math.cos(d)), R); w.rotation.z = d;
59	          w.userData.t.children[0].material = i === 1 && !steered && Math.abs(steer) > 2 * D ? scrubMat : tyreMat;
60	          // The wheel's axis, from its kingpin out to the rear-axle line (y where it crosses: ±k + wb / tan δ).
61	          const y = Math.abs(d) > 1e-4 ? side * k + (a.x - x0) / Math.tan(d) : Infinity, line = a.lines[j];
62	          line.visible = Number.isFinite(y) && Math.abs(y) < FAR;
63	          if (line.visible) { const g = line.geometry.attributes.position; g.setXYZ(0, a.x, side * k, 0.05); g.setXYZ(1, x0, y, 0.05); g.needsUpdate = true; line.computeLineDistances(); }
64	        });
65	      });
66	      // Drag link: from the first axle's left arm end to the second's.
67	      const end = (a, s) => tmp.set(a.x + m(s.PL[0]), m(s.PL[1]), R + 0.05).clone();
68	      place(link, end(axles[0], r.s1), end(axles[1], r.s2));
69	      const c = r.centre;
70	      centre.visible = Number.isFinite(c) && Math.abs(m(c)) < FAR; if (centre.visible) centre.position.set(x0, m(c), 0.05);
71	      const io = s => { const a = [Math.abs(s.dL), Math.abs(s.dR)].sort((u, v) => v - u); return `${(a[0] / D).toFixed(0)} / ${(a[1] / D).toFixed(0)}`; };   // whole degrees: num() only localises a lone number
72	      ui.set("a1", io(r.s1)); ui.set("a2", io(r.s2));
73	      ui.set("radius", Number.isFinite(c) ? (Math.abs(c) / 1000).toFixed(1) : "–"); ui.set("scrub", (r.scrub / D).toFixed(1));
74	      ui.badge("state").set(steered ? t("All wheel axes meet at one point") : t("Fixed second axle: its tyres scrub"), steered);
75	    },
76	  };
77	}
