content.text:
1	// Front steering seen from above: Benz's double-pivot (stub-axle) trapezoid against the older centre-pivot turntable axle,
2	// with each front wheel's axis drawn out to the rear-axle line (where they meet = the turning centre).
3	// Params (mm, deg): label, kingpinHalf, arm, wheelbase, frontR, rearR, halfTrackRear, stub (kingpin → wheel centre),
4	// maxSteer, start? ("dp" | "cp": the layout shown first, default double pivot). Vehicle frame: rear axle at x = 0, front axle at x = wheelbase.
5	import * as THREE from "three";
6	import { V, mat, rod, place, ball, spokedWheel } from "../lib/scene/helpers.js";
7	import { createDoublePivot, centrePivot } from "../lib/model/steering.js";
8	
9	const D = Math.PI / 180, FAR = 40;   // m: axis lines longer than this are not drawn (nearly straight ahead)
10	
11	export function create(ctx, p) {
12	  const { stage, carRoot, t } = ctx;
13	  const sys = createDoublePivot({ kingpinHalf: p.kingpinHalf, arm: p.arm, wheelbase: p.wheelbase });
14	  const m = v => v / 1000, wb = m(p.wheelbase), k = m(p.kingpinHalf), zF = m(p.frontR), zR = m(p.rearR), stub = m(p.stub ?? 60);
15	  const group = new THREE.Group(); carRoot.add(group);
16	  const wood = mat(0x8a6a4a, { roughness: 0.8 }), iron = mat(0x4a5058, { metalness: 0.4 }), tyreMat = mat(0x2a2d31, { roughness: 0.9 });
17	  for (const w of [wood, tyreMat]) w.transparent = true;   // wheels fade over the museum photo
18	  const armMat = stage.tokenMat("--l1"), tieMat = stage.tokenMat("--l2"), beamMat = stage.tokenMat("--metal");
19	
20	  // Rear axle and wheels, fixed.
21	  group.add(place(rod(iron, 0.02), V(0, -m(p.halfTrackRear), zR), V(0, m(p.halfTrackRear), zR)));
22	  for (const s of [1, -1]) { const w = spokedWheel(tyreMat, wood, zR, 14); w.position.set(0, s * m(p.halfTrackRear), zR); group.add(w); }
23	
24	  // Front beam: fixed in double-pivot mode, swings about its centre in centre-pivot mode. Each wheel turns on its own
25	  // kingpin at the beam end (double pivot) or is fixed to the beam (centre pivot).
26	  const beam = new THREE.Group(); beam.position.set(wb, 0, zF); group.add(beam);
27	  beam.add(place(rod(beamMat, 0.022), V(0, -k, 0), V(0, k, 0)));
28	  const turntable = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.012, 8, 40), iron); turntable.position.set(wb, 0, zF + 0.03); group.add(turntable);
29	  const corners = [1, -1].map(side => {
30	    const pivot = new THREE.Group(); pivot.position.set(0, side * k, 0); beam.add(pivot);
31	    pivot.add(place(rod(iron, 0.012), V(0, 0, -0.06), V(0, 0, 0.06)));   // kingpin
32	    pivot.add(place(rod(iron, 0.014), V(0, 0, 0), V(0, side * stub, 0)));   // stub axle
33	    const w = spokedWheel(tyreMat, wood, zF, 12); w.position.set(0, side * stub, 0); pivot.add(w);
34	    const [ax, ay] = sys.armVec(side, 0);
35	    const arm = place(rod(armMat, 0.012), V(0, 0, 0), V(m(ax), m(ay), 0)); pivot.add(arm);
36	    return { pivot, arm };
37	  });
38	  const tie = rod(tieMat, 0.01); group.add(tie);
39	
40	  // Axis lines on the ground to the rear-axle line, and the turning centre(s) where they land.
41	  const lineOf = token => {
42	    const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints([V(0, 0, 0), V(0, 0, 0)]), new THREE.LineBasicMaterial({ transparent: true, opacity: 0.9 }));
43	    stage.bind(l.material.color, token); l.frustumCulled = false; group.add(l); return l;
44	  };
45	  const axisL = lineOf("--l1"), axisR = lineOf("--l2"), rearLine = lineOf("--muted");
46	  const icrL = ball(stage.tokenMat("--l1"), 0.05), icrR = ball(stage.tokenMat("--l2"), 0.05); group.add(icrL, icrR);
47	  const setLine = (l, a, b) => { const pos = l.geometry.attributes.position; pos.setXYZ(0, a.x, a.y, a.z); pos.setXYZ(1, b.x, b.y, b.z); pos.needsUpdate = true; };
48	  const G = 0.01;   // line height above the ground
49	
50	  let mode = p.start ?? "dp", steer = 0, auto = !ctx.reducedMotion, clock = 0;
51	  const maxS = p.maxSteer ?? 30;
52	  const setMode = md => { mode = md; ui.toggle("dp").set(md === "dp"); ui.toggle("cp").set(md === "cp"); };
53	
54	  const ui = ctx.panel([
55	    { label: p.label, items: [
56	      { buttons: [{ id: "dp", label: t("Double-pivot (Benz, 1893)"), pressed: mode === "dp", onClick: () => setMode("dp") },
57	        { id: "cp", label: t("Centre-pivot axle"), pressed: mode === "cp", onClick: () => setMode("cp") }] },
58	      { slider: { id: "steer", label: t("Steering angle (+ = left)"), min: -maxS, max: maxS, value: 0, onInput: v => { auto = false; ui.toggle("auto").set(false); steer = v * D; } } },
59	      { readouts: [{ id: "inner", label: t("Inner wheel"), unit: t("deg") }, { id: "outer", label: t("Outer wheel"), unit: t("deg") },
60	        { id: "ideal", label: t("Ideal outer"), unit: t("deg, all axes meet") }, { id: "miss", label: t("Axes miss by"), unit: t("m at the rear axle") },
61	        { id: "radius", label: t("Turning circle"), unit: t("m radius, outer front") }, { id: "support", label: t("Front support width"), unit: t("% of straight ahead") }] },
62	      { buttons: [{ id: "auto", toggle: [t("Auto demo on"), t("Auto demo off")], pressed: auto, onClick: v => (auto = v) }] },
63	      { key: [["--l1", t("left wheel axis")], ["--l2", t("right wheel axis")], ["--muted", t("rear axle line")]] },
64	    ] },
65	    { label: t("Parts"), items: [{ legend: [["--l1", t("Steering arms")], ["--l2", t("Tie rod")], ["--metal", t("Front axle beam")]] }] },
66	  ]);
67	
68	  function pose() {
69	    const front = K => V(wb + m(K[0]), m(K[1]), G);
70	    const toRear = (from, d) => V(0, from.y + from.x / Math.tan(d), G);   // along the wheel axis to x = 0
71	    let r;
72	    if (mode === "dp") {
73	      const s = sys.solve(steer);
74	      beam.rotation.z = 0; corners[0].pivot.rotation.z = s.dL; corners[1].pivot.rotation.z = s.dR;
75	      place(tie, V(wb + m(s.PL[0]), m(s.PL[1]), zF), V(wb + m(s.PR[0]), m(s.PR[1]), zF));
76	      const inner = Math.max(Math.abs(s.dL), Math.abs(s.dR)), outer = Math.min(Math.abs(s.dL), Math.abs(s.dR));
77	      r = { inner, outer, ideal: Math.abs(s.idealOuter), miss: Math.abs(s.icrL - s.icrR), radius: s.radius, support: 1, dL: s.dL, dR: s.dR, KL: front(s.KL), KR: front(s.KR) };
78	    } else {
79	      const c = centrePivot({ kingpinHalf: p.kingpinHalf, wheelbase: p.wheelbase }, steer);
80	      beam.rotation.z = steer; corners[0].pivot.rotation.z = 0; corners[1].pivot.rotation.z = 0;
81	      r = { inner: Math.abs(steer), outer: Math.abs(steer), ideal: Math.abs(steer), miss: 0, radius: c.radius, support: c.halfTrack / p.kingpinHalf, dL: steer, dR: steer, KL: front(c.L), KR: front(c.R) };
82	    }
83	    for (const c of corners) c.arm.visible = mode === "dp";
84	    tie.visible = mode === "dp"; turntable.visible = mode === "cp";
85	    const straight = Math.abs(steer) < 0.5 * D;
86	    const eL = straight ? null : toRear(r.KL, r.dL), eR = straight ? null : toRear(r.KR, r.dR);
87	    const show = !straight && Math.abs(eL.y) < FAR && Math.abs(eR.y) < FAR;
88	    for (const o of [axisL, axisR, rearLine, icrL, icrR]) o.visible = show;
89	    if (show) {
90	      setLine(axisL, r.KL, eL); setLine(axisR, r.KR, eR);
91	      const ys = [eL.y, eR.y, -m(p.halfTrackRear), m(p.halfTrackRear)];
92	      setLine(rearLine, V(0, Math.min(...ys), G), V(0, Math.max(...ys), G));
93	      icrL.position.copy(eL); icrR.position.copy(eR);
94	    }
95	    return r;
96	  }
97	  pose();
98	
99	  return {
100	    layout({ active, onPhoto }) { group.visible = active; wood.opacity = tyreMat.opacity = onPhoto ? 0.25 : 1; },
101	    update(dt) {
102	      if (auto) { clock += dt; steer = maxS * D * Math.sin(clock * 0.6); ui.slider("steer").set((steer / D).toFixed(1)); }
103	      const r = pose(), straight = Math.abs(steer) < 0.5 * D;
104	      ui.set("inner", (r.inner / D).toFixed(1)); ui.set("outer", (r.outer / D).toFixed(1));
105	      ui.set("ideal", straight ? "0.0" : (r.ideal / D).toFixed(1));
106	      ui.set("miss", straight ? "–" : (r.miss / 1000).toFixed(2));
107	      ui.set("radius", straight ? t("straight") : (r.radius / 1000).toFixed(1));
108	      ui.set("support", Math.round(r.support * 100));
109	    },
110	  };
111	}
