// Teaser page (teaser.html): the teaser stops as scroll stories (story.js), one after the other. Each story links its stop
// page with &r=teaser, so the stop pages page between these stops.
import tour, { teaser } from "../../stops/tour.js";
import { showOfflineStatus } from "./offline.js";
import { t, loadCar, localizePage, missing } from "./i18n.js";
import { h } from "./dom.js";
import { story, play } from "./story.js";

localizePage();
showOfflineStatus(document.getElementById("status"));
const cars = await Promise.all(tour.filter(s => teaser.includes(s.slug)).map(s => loadCar(s.slug)));
const credits = [...new Set(cars.filter(c => c.photo).map(c => `${c.photo.credit.author} (${c.photo.credit.license})`))];
document.getElementById("credits").textContent = t("Photos via Wikimedia Commons: {0}; each car's page links its photo's source.", credits.join(", "));

const stories = cars.map(car => story(car, { more: h("a", { class: "pill primary", href: `stop.html?s=${car.slug}&r=teaser` }, t("Open this car on its own page")) }));
document.getElementById("cars").replaceChildren(...stories.map(s => s.el));
const handles = await play(stories);
if (new URLSearchParams(location.search).has("debug")) window.__tour = { stories: handles, missing: () => [...missing], ready: true };
<body>
<header class="bar"><div class="crumbs">
  <span class="home" data-i18n>Under the skin</span>
  <span class="where" data-i18n>Unofficial tour notes</span>
  <div class="langs" role="group" aria-label="Language · Nyelv · Sprache"><button type="button" data-lang="en" lang="en" aria-label="English">EN</button><button type="button" data-lang="hu" lang="hu" aria-label="Magyar">HU</button><button type="button" data-lang="de" lang="de" aria-label="Deutsch">DE</button></div>
</div></header>
<section class="hero">
  <img src="stops/w196r/photo.jpg" alt="" width="1200" height="803" fetchpriority="high">
  <div class="copy">
    <div class="eyebrow" data-i18n>Mercedes-Benz Museum · Stuttgart</div>
    <h1 data-i18n>Under the skin: a technical tour</h1>
    <p class="lede" data-i18n>At each stop, open the car's page and watch one of its mechanisms working. Scroll to see where the mechanism sits under the bodywork. The route runs from Level 8 down, in the museum's own order.</p>
    <div class="actions"><a class="pill primary" href="#jump" data-i18n>Find your room</a><a class="pill" href="teaser.html" data-i18n>Three highlights</a></div>
    <p class="status" id="status" role="status" data-i18n>Checking offline mode…</p>
  </div>
</section>
<main class="wrap">
  <nav class="jump" id="jump" aria-labelledby="jump-title" hidden><h2 id="jump-title" data-i18n>Jump to a room</h2><ul></ul></nav>
  <ol class="route" id="route"><li class="note" data-i18n>Loading the route…</li></ol>
  <footer>
    <p data-i18n>Open the tour while you’re online. When you see “Ready offline”, every stop is saved on this device. On iPhone or iPad, Share → Add to Home Screen keeps it saved for longer.</p>
    <p class="note"><span data-i18n>Unofficial private tour notes, not affiliated with Mercedes-Benz. Rooms and levels follow research notes: confirm on site, exhibits rotate.</span> <span id="credits"></span> <span data-i18n>3D: three.js (MIT). Headlines: Instrument Serif (SIL OFL).</span></p>
  </footer>
</main>
<script type="module" src="lib/app/index.js"></script>
</body>

