python3 - <<'EOF'
def sub(p, old, new):
    s=open(p).read(); assert old in s, (p, old[:60]); open(p,'w').write(s.replace(old,new))
sub('lib/model/differential.js','''// Open and locked differentials. Pure: no DOM, no three.js. Units: m, s, N, rad/s.''','''// Open, limited-slip and locked differentials. Pure: no DOM, no three.js. Units: m, s, N, rad/s.''')
sub('lib/model/differential.js','''// Drive force on an axle. Open: both sides always get the same torque, so the wheel with less grip limits both.
// Locked: the axle turns as one shaft and each wheel can push up to its own grip.
// p = { torque (N·m at the axle), wheelR, normal (N per wheel), muL, muR, locked, resist (N needed to move the car) }.
export function traction({ torque, wheelR, normal, muL, muR, locked, resist = 0 }) {
  const gripL = muL * normal, gripR = muR * normal, want = torque / wheelR;
  let fL, fR, spinL, spinR;
  if (locked) {
    const grip = gripL + gripR, f = Math.min(want, grip);
    fL = grip ? f * gripL / grip : 0; fR = f - fL;
    spinL = spinR = want > grip;
  } else {
    // The wheel with less grip spins first; that caps the torque on both sides, so the other wheel never spins.
    const each = Math.min(want / 2, gripL, gripR);
    fL = fR = each;
    spinL = want / 2 > gripL && gripL <= gripR; spinR = want / 2 > gripR && gripR <= gripL;
  }''','''// Drive force on an axle. Open: both sides always get the same torque, so the wheel with less grip limits both.
// Limited-slip (bias > 1): friction plates between a side gear and the carrier resist the two sides turning apart, so
// while one wheel slips the other can take up to `bias` times its torque (the torque bias ratio). Locked: the axle turns
// as one shaft and each wheel can push up to its own grip.
// p = { torque (N·m at the axle), wheelR, normal (N per wheel), muL, muR, locked, bias (1 = open), resist (N needed to
// move the car) }.
export function traction({ torque, wheelR, normal, muL, muR, locked, bias = 1, resist = 0 }) {
  const gripL = muL * normal, gripR = muR * normal, want = torque / wheelR;
  let fL, fR, spinL, spinR;
  if (locked) {
    const grip = gripL + gripR, f = Math.min(want, grip);
    fL = grip ? f * gripL / grip : 0; fR = f - fL;
    spinL = spinR = want > grip;
  } else if (want / 2 <= Math.min(gripL, gripR)) {
    fL = fR = want / 2; spinL = spinR = false;   // nothing slips: equal shares
  } else {
    // The wheel with less grip slips at its grip. Open, that caps the other side too (bias 1), so it never spins unless
    // its grip is no better; with plates the other side may carry up to `bias` times as much.
    const lowL = gripL <= gripR, lo = Math.min(gripL, gripR), hi = Math.max(gripL, gripR);
    const fHi = Math.min(want - lo, Math.max(1, bias) * lo, hi);
    const spinLo = true, spinHi = fHi >= hi - 1e-9 && want > lo + hi;
    [fL, fR] = lowL ? [lo, fHi] : [fHi, lo];
    [spinL, spinR] = lowL ? [spinLo, spinHi] : [spinHi, spinLo];
  }''')
sub('tests/unit/drivetrain.test.mjs','''  const both = traction({ ...p, muL: 0.7, locked: false });
  assert.ok(both.spinL && both.spinR, "equal grip, too much torque: both spin");
});''','''  const both = traction({ ...p, muL: 0.7, locked: false });
  assert.ok(both.spinL && both.spinR, "equal grip, too much torque: both spin");
});

test("differential: a limited-slip differential passes up to its bias ratio to the wheel with grip, between open and locked", () => {
